import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第十四章 法律责任","description":"","frontmatter":{"title":"第十四章 法律责任","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第十四章：法律责任.md"},"headers":[],"relativePath":"blogs/CL/dishisizhang：falvzeren.md","filePath":"blogs/CL/第十四章：法律责任.md"}'),h={name:"blogs/CL/dishisizhang：falvzeren.md"};function i(l,a,n,d,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="第十四章-法律责任" tabindex="-1">第十四章 法律责任 <a class="header-anchor" href="#第十四章-法律责任" aria-label="Permalink to &quot;第十四章 法律责任&quot;">​</a></h1><h3 id="第二百五十条" tabindex="-1">第二百五十条 <a class="header-anchor" href="#第二百五十条" aria-label="Permalink to &quot;第二百五十条&quot;">​</a></h3><p>十条违反本法规定，虚报注册资本、提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得公司登记的，由公司登记机关责令改正，对虚报注册资本的公司，处以虚报注册资本金额百分之五以上百分之十五以下的罚款；对提交虚假材料或者采取其他欺诈手段隐瞒重要事实的公司，处以五万元以上二百万元以下的罚款；情节严重的，吊销营业执照；对直接负责的主管人员和其他直接责任人员处以三万元以上三十万元以下的罚款。</p><h3 id="第二百五十一条" tabindex="-1">第二百五十一条 <a class="header-anchor" href="#第二百五十一条" aria-label="Permalink to &quot;第二百五十一条&quot;">​</a></h3><p>一条公司未依照本法第四十条规定公示有关信息或者不如实公示有关信息的，由公司登记机关责令改正，可以处以一万元以上五万元以下的罚款。情节严重的，处以五万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员处以一万元以上十万元以下的罚款。</p><h3 id="第二百五十二条" tabindex="-1">第二百五十二条 <a class="header-anchor" href="#第二百五十二条" aria-label="Permalink to &quot;第二百五十二条&quot;">​</a></h3><p>二条公司的发起人、股东虚假出资，未交付或者未按期交付作为出资的货币或者非货币财产的，由公司登记机关责令改正，可以处以五万元以上二十万元以下的罚款；情节严重的，处以虚假出资或者未出资金额百分之五以上百分之十五以下的罚款；对直接负责的主管人员和其他直接责任人员处以一万元以上十万元以下的罚款。</p><h3 id="第二百五十三条" tabindex="-1">第二百五十三条 <a class="header-anchor" href="#第二百五十三条" aria-label="Permalink to &quot;第二百五十三条&quot;">​</a></h3><p>三条公司的发起人、股东在公司成立后，抽逃其出资的，由公司登记机关责令改正，处以所抽逃出资金额百分之五以上百分之十五以下的罚款；对直接负责的主管人员和其他直接责任人员处以三万元以上三十万元以下的罚款。</p><h3 id="第二百五十四条" tabindex="-1">第二百五十四条 <a class="header-anchor" href="#第二百五十四条" aria-label="Permalink to &quot;第二百五十四条&quot;">​</a></h3><p>四条有下列行为之一的，由县级以上人民政府财政部门依照《中华人民共和国会计法》等法律、行政法规的规定处罚： （一）在法定的会计账簿以外另立会计账簿； （二）提供存在虚假记载或者隐瞒重要事实的财务会计报告。</p><h3 id="第二百五十五条" tabindex="-1">第二百五十五条 <a class="header-anchor" href="#第二百五十五条" aria-label="Permalink to &quot;第二百五十五条&quot;">​</a></h3><p>五条公司在合并、分立、减少注册资本或者进行清算时，不依照本法规定通知或者公告债权人的，由公司登记机关责令改正，对公司处以一万元以上十万元以下的罚款。</p><h3 id="第二百五十六条" tabindex="-1">第二百五十六条 <a class="header-anchor" href="#第二百五十六条" aria-label="Permalink to &quot;第二百五十六条&quot;">​</a></h3><p>六条公司在进行清算时，隐匿财产，对资产负债表或者财产清单作虚假记载，或者在未清偿债务前分配公司财产的，由公司登记机关责令改正，对公司处以隐匿财产或者未清偿债务前分配公司财产金额百分之五以上百分之十以下的罚款；对直接负责的主管人员和其他直接责任人员处以一万元以上十万元以下的罚款。</p><h3 id="第二百五十七条" tabindex="-1">第二百五十七条 <a class="header-anchor" href="#第二百五十七条" aria-label="Permalink to &quot;第二百五十七条&quot;">​</a></h3><p>七条承担资产评估、验资或者验证的机构提供虚假材料或者提供有重大遗漏的报告的，由有关部门依照《中华人民共和国资产评估法》、《中华人民共和国注册会计师法》等法律、行政法规的规定处罚。 承担资产评估、验资或者验证的机构因其出具的评估结果、验资或者验证证明不实，给公司债权人造成损失的，除能够证明自己没有过错的外，在其评估或者证明不实的金额范围内承担赔偿责任。</p><h3 id="第二百五十八条" tabindex="-1">第二百五十八条 <a class="header-anchor" href="#第二百五十八条" aria-label="Permalink to &quot;第二百五十八条&quot;">​</a></h3><p>八条公司登记机关违反法律、行政法规规定未履行职责或者履行职责不当的，对负有责任的领导人员和直接责任人员依法给予政务处分。</p><h3 id="第二百五十九条" tabindex="-1">第二百五十九条 <a class="header-anchor" href="#第二百五十九条" aria-label="Permalink to &quot;第二百五十九条&quot;">​</a></h3><p>九条未依法登记为有限责任公司或者股份有限公司，而冒用有限责任公司或者股份有限公司名义的，或者未依法登记为有限责任公司或者股份有限公司的分公司，而冒用有限责任公司或者股份有限公司的分公司名义的，由公司登记机关责令改正或者予以取缔，可以并处十万元以下的罚款。</p><h3 id="第二百六十条" tabindex="-1">第二百六十条 <a class="header-anchor" href="#第二百六十条" aria-label="Permalink to &quot;第二百六十条&quot;">​</a></h3><p>十条公司成立后无正当理由超过六个月未开业的，或者开业后自行停业连续六个月以上的，公司登记机关可以吊销营业执照，但公司依法办理歇业的除外。 公司登记事项发生变更时，未依照本法规定办理有关变更登记的，由公司登记机关责令限期登记；逾期不登记的，处以一万元以上十万元以下的罚款。</p><h3 id="第二百六十一条" tabindex="-1">第二百六十一条 <a class="header-anchor" href="#第二百六十一条" aria-label="Permalink to &quot;第二百六十一条&quot;">​</a></h3><p>一条外国公司违反本法规定，擅自在中华人民共和国境内设立分支机构的，由公司登记机关责令改正或者关闭，可以并处五万元以上二十万元以下的罚款。</p><h3 id="第二百六十二条" tabindex="-1">第二百六十二条 <a class="header-anchor" href="#第二百六十二条" aria-label="Permalink to &quot;第二百六十二条&quot;">​</a></h3><p>二条利用公司名义从事危害国家安全、社会公共利益的严重违法行为的，吊销营业执照。</p><h3 id="第二百六十三条" tabindex="-1">第二百六十三条 <a class="header-anchor" href="#第二百六十三条" aria-label="Permalink to &quot;第二百六十三条&quot;">​</a></h3><p>三条公司违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金的，其财产不足以支付时，先承担民事赔偿责任。</p><h3 id="第二百六十四条" tabindex="-1">第二百六十四条 <a class="header-anchor" href="#第二百六十四条" aria-label="Permalink to &quot;第二百六十四条&quot;">​</a></h3><p>四条违反本法规定，构成犯罪的，依法追究刑事责任。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',33)])])}const b=e(h,[["render",i]]);export{u as __pageData,b as default};
